//! Group 4 — no option id is MID-WORD truncated relative to its label.
//!
//! Option ids were once machine-generated by slugifying the label and cutting at a 48-char
//! cap. Many landed mid-word (`…-downstrea`, `…-persisten`, `explicit-load`), and they are
//! client-visible as `convention_option_id` / `observed_options[].option_id` in
//! `findings.json` and the xlsx — a broken-looking data field a client reads. This gate is the
//! durable "fix the generator": it fails on any option id that is a strict prefix of its
//! label's slug AND is cut in the MIDDLE of a word (the next slug character is not a `-`).
//!
//! Deliberately NOT flagged: a concise hand-authored id that is shorter than the full label
//! slug but ends on a word boundary (`parameterized-queries` for a longer label). Those read
//! as complete noun phrases — the house style the authoring guide prescribes — and are the
//! intended end state, not a defect. The line this gate draws is broken (mid-word) vs. readable
//! (boundary-complete), not short vs. long.

use camerata_rules::{corpus_path, load_corpus_lenient};

/// Lowercase-kebab slug of a label: alphanumerics pass through lowercased, every other run of
/// characters collapses to a single `-`, leading/trailing `-` trimmed. Matches the historical
/// generator and `slugify_decision_label`.
fn slug(label: &str) -> String {
    let mut out = String::with_capacity(label.len());
    let mut prev_dash = false;
    for ch in label.chars() {
        if ch.is_ascii_alphanumeric() {
            out.push(ch.to_ascii_lowercase());
            prev_dash = false;
        } else if !prev_dash && !out.is_empty() {
            out.push('-');
            prev_dash = true;
        }
    }
    out.trim_matches('-').to_string()
}

/// True when `id` is `label_slug` cut off in the middle of a word — i.e. `id` is a strict
/// prefix of `label_slug` and the first dropped character is not a word boundary (`-`).
fn is_midword_truncation(id: &str, label_slug: &str) -> bool {
    if id == label_slug || !label_slug.starts_with(id) {
        return false;
    }
    // The character immediately after the prefix: if it is not a dash, the id was cut inside a
    // word. `label_slug` is strictly longer here, so indexing `id.len()` is in bounds.
    label_slug.as_bytes().get(id.len()).copied() != Some(b'-')
}

#[tokio::test]
async fn req_group4_no_option_id_is_midword_truncated() {
    let (corpus, errors) = load_corpus_lenient(&corpus_path()).await;
    assert!(errors.is_empty(), "corpus must load cleanly: {errors:?}");

    let mut offenders: Vec<String> = Vec::new();
    for rule in corpus.iter() {
        for opt in &rule.options {
            let label_slug = slug(&opt.label);
            if is_midword_truncation(&opt.id, &label_slug) {
                offenders.push(format!("{} / {}  ->  {}", rule.id.0, opt.id, label_slug));
            }
        }
    }
    assert!(
        offenders.is_empty(),
        "these option ids are cut mid-word (machine truncation); de-truncate each to the full \
         label slug, updating any `[decision].default` and Rust reference in lockstep:\n  {}",
        offenders.join("\n  ")
    );
}
